import {escapeHTML as e} from '/model.mjs';
export async function renderStaff(out,api){
  const view=crypto.randomUUID();out.dataset.officeView=view;
  out.innerHTML='<div class="heading"><span class="eyebrow">Authorised door team</span><h1>The right people. At the door.</h1><p>Invite individual staff, assign their events and share the phone installation link.</p></div><div class="panel" id="staff-body">Loading the door team…</div>';
  try{const office=await api('/api/admin/staff');if(out.dataset.officeView!==view)return;
    out.querySelector('#staff-body').outerHTML=`<div class="panel staff-install"><div><h2>Install Ringside Door</h2><p>Share this link with your door team. iPhone: open in Safari, tap Share, then Add to Home Screen. Android: open in Chrome and choose Install app / Add to Home screen.</p><p><a href="${e(office.installURL)}" target="_blank" rel="noopener">${e(office.installURL)}</a></p><p><a href="/door/install/" target="_blank" rel="noopener">Step-by-step phone setup →</a></p><p>Installation does not grant access. Every scanner needs their own account, authenticator and event assignment.</p></div><img src="/api/door/install-qr" alt="Scan to open the staff app on your phone"></div><div class="panel"><h2>Add a team member</h2><p>${office.invitesEnabled?'Invitations use the verified account-email sender.':'Invitations await the protected server connection. You can still add an account already created in Supabase.'}</p><form id="staff-invite"><div class="fields"><label class="field"><span>Staff email</span><input name="email" type="email" required maxlength="254" autocomplete="off"></label><label class="field"><span>Role</span><select name="role"><option value="scanner">Door scanner</option><option value="editor">Website editor</option></select></label><label class="field"><span>Account setup</span><select name="action"><option value="invite">Send a new invitation</option><option value="grant">Add existing account</option></select></label></div><button type="submit">Add team member</button></form></div><div class="panel"><h2>Accounts & event assignments</h2>${office.staff.map(person=>`<article class="staff-person"><div class="row-heading"><div><h3>${e(person.email)}</h3><p>${e(person.role)} · ${person.active?'Active':'Paused'} · ${person.verified?'Email verified':'Awaiting email verification'}</p></div>${person.role!=='owner'?`<button data-staff-active="${e(person.id)}" data-active="${!person.active}">${person.active?'Pause access':'Restore access'}</button>`:''}</div>${person.active&&['owner','scanner'].includes(person.role)?`<div class="fields">${office.events.map(event=>`<label class="staff-assignment"><input type="checkbox" data-assign-user="${e(person.id)}" data-assign-event="${e(event.id)}" ${person.events.includes(event.id)?'checked':''}><span>${e(event.title)}<small>${e(event.status)} · ${e(new Date(event.startsAt).toLocaleDateString('en-GB'))}</small></span></label>`).join('')||'<p>Publish an event before assigning a scanner.</p>'}</div>`:''}</article>`).join('')}</div>`;
  }catch(error){if(out.dataset.officeView===view)out.querySelector('#staff-body').textContent=error.message;}
}
